<?php require 'partials.php';$uid=require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT g.*,q.title FROM jolt_games g JOIN jolt_quizzes q ON q.id=g.quiz_id WHERE g.id=? AND g.host_user_id=?');$s->bind_param('ii',$id,$uid);$s->execute();$g=$s->get_result()->fetch_assoc();if(!$g)exit('Jolten hittades inte.');$playBase=PLAY_URL?:((isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.$_SERVER['HTTP_HOST'].rtrim(dirname($_SERVER['SCRIPT_NAME']),'/\\'));$joinUrl=rtrim($playBase,'/').'/play.php?code='.$g['code'];page_top('Live: '.$g['title']);?>
<section class="live-shell" data-game="<?=$id?>" data-music="<?=e($g['music_theme'])?>"><header class="live-top"><a class="logo" href="dashboard.php">JOLT⚡</a><div id="liveMeta"></div><button id="musicToggle">♫</button></header><div id="hostStage" class="host-stage"><div class="lobby"><span class="eyebrow">DELTAGARE</span><p>Skanna QR-koden eller gå till <a href="<?=e($joinUrl)?>" style="color:var(--lime);font-weight:800;text-decoration:underline"><?=e($playBase)?></a></p><div class="live-join-qr"><div id="liveJoinQr"></div></div><h1><?=$g['code']?></h1><p>Väntar på deltagare…</p><div id="players" class="player-cloud"></div><button id="hostAction">Starta Jolt ⚡</button></div></div></section>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>new QRCode(document.querySelector('#liveJoinQr'),{text:<?=json_encode($joinUrl,JSON_UNESCAPED_SLASHES)?>,width:190,height:190,correctLevel:QRCode.CorrectLevel.H});window.JOLT={gameId:<?=$id?>,csrf:'<?=csrf()?>',role:'host',music:'<?=e($g['music_theme'])?>'}</script><script src="assets/live.js"></script><?php page_bottom();?>
